import {createCompanyTemplates,normalizeCompanyAssets} from './company-templates.js';
import {createAssistantPanel} from './assistant-panel.js';
const $=s=>document.querySelector(s), uid=()=>crypto.randomUUID(),today=()=>new Date().toISOString().slice(0,10);
const account=currentAccount(),organisation=account?.organisation||demoOrganisation,workspaceKey=organisation.id==='demo'?'current':'org:'+organisation.id;
let workspace={projects:[]},currentId='',page='overview',libraryTab='files',groupBy='discipline',chartType='line',scope='All',query='',category='All categories',taskPage=1,taskFilter='All statuses',assistantMessages=[],storageError=false,modalFocus=null;
let pendingFile=null,pendingSheets=[],pendingSheet=0,pendingCatalog=null,activeReport=null,returnToReview=false,pendingDate='',importBusy=false;
const pageNames={overview:'My project',data:'Files',tasks:'Activities',reports:'Reports',slides:'Slides',insights:'Project assistant',settings:'Workspace settings'};
const project=()=>workspace.projects.find(p=>p.id===currentId)||workspace.projects[0];
const slideStudio=createSlideStudio({getProject:project,persist,toast,openModal,closeModal,render,decorateDeck:d=>companyTemplates.decorate(d),companyGallery:()=>companyTemplates.gallery(),saveCompanyStyle:d=>companyTemplates.saveDeck(d)});
const reportLibrary=createReportLibrary({getProject:project,persist,toast,openModal,closeModal,render,author:()=>account?.name||'Demo planner',edit:value=>{activeReport=value;renderReportModal();}});
const uploadQueue=createUploadQueue({getProject:project,persist,toast,openModal,closeModal,render,review:(job,date)=>startImport(job.file,job.sheet.catalogId,[job.sheet],date),reviewProject:reviewModal,commit:commitQueuedDataset,pick:callback=>pickFile('.csv,.tsv,.xlsx',callback,true)});
const companyTemplates=createCompanyTemplates({getProject:project,getWorkspace:()=>workspace,persist,toast,openModal,closeModal,render,getReport:()=>{gatherReport();return activeReport;},applyReport:t=>{activeReport={id:t.templateId,format:t.format||'pdf',options:{...defaultOptions(t.templateId),...t.options,scope:'All',from:'',to:'',commentary:''}};renderReportModal();},useSlides:d=>{slideStudio.addDeck(d);navigate('slides');}});
const assistant=createAssistantPanel({getProject:project,toast,getContext:()=>({label:pageNames[page],groupBy:$('#report-form')?activeReport.options.groupBy:groupBy,options:$('#report-form')?activeReport.options:{scope},reportOpen:!!$('#report-form'),source:$('#report-form')?(activeReport.source||companyTemplates.branded(project())):null,...(page==='slides'?slideStudio.context():{})}),showSource:id=>{const back=!!$('#report-form');if(back)gatherReport();viewDataset(id);if(back)$('#dialog .modal-body').insertAdjacentHTML('beforeend','<div class="modal-actions"><button class="button" data-action="resume-report">Back to report</button></div>');},applySummary:text=>{if(!$('#report-form'))throw new Error('Open a report before applying commentary.');gatherReport();activeReport.options.commentary=text;renderReportModal();}});
function toast(message,error=false){const node=document.createElement('div');node.className='toast '+(error?'error':'');node.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`;$('#toast-root').append(node);setTimeout(()=>node.remove(),5500);}
async function persist(){try{await saveWorkspace(workspace,workspaceKey);storageError=false;return true;}catch(e){storageError=true;toast('Changes could not be saved in this browser. Export a workspace backup before closing.',true);return false;}}
function navigate(next){slideStudio.flush();page=next;if(next==='data')libraryTab='files';query='';category='All categories';taskPage=1;render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});}
function button(text,action,style='button',extra=''){return `<button class="${style}" data-action="${action}" ${extra}>${text}</button>`;}
function shell(){const p=project();return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-page="overview"><img src="./favicon.svg" alt=""/><span>Planvisiq<span class="brand-dot">.</span></span></a><a class="workspace-switch" href="./organisation.html" title="Organisation setup"><span class="workspace-avatar">${esc(initials(organisation.name))}</span><div><strong>${esc(organisation.name)}</strong><small>${organisation.demo?'Demo workspace':'Local company preview'}</small></div>${icon('chevron')}</a><p class="nav-label">WORKSPACE</p><nav>${[['overview','dashboard'],['data','folder'],['reports','file'],['slides','presentation']].map(([key,ic])=>`<button data-action="nav" data-page="${key}" class="nav-item ${page===key?'active':''}">${icon(ic)}<span>${pageNames[key]}</span>${key==='data'?`<b>${p.datasets.length}</b>`:key==='insights'?'<i></i>':''}</button>`).join('')}</nav><details class="more-navigation" ${['tasks','insights','settings'].includes(page)?'open':''}><summary>More tools ${icon('down')}</summary>${button(icon('tasks')+'Activities','nav','nav-item '+(page==='tasks'?'active':''),'data-page="tasks"')}${button(icon('spark')+'Project assistant','nav','nav-item '+(page==='insights'?'active':''),'data-page="insights"')}</details><div class="sidebar-callout"><div class="callout-icon">${icon('file')}</div><strong>From files to findings.</strong><p>Your next stakeholder report starts here.</p>${button('Create a report '+icon('arrow'),'new-report','text-button')}</div><div class="nav-bottom"><a href="./learn.html" class="nav-item">${icon('presentation')}Learn Planvisiq</a><a href="./organisation.html" class="nav-item">${icon('briefcase')}Organisation</a><a href="./index.html" class="nav-item">${icon('external')}Home page</a>${button(icon('settings')+'Settings','nav','nav-item '+(page==='settings'?'active':''),'data-page="settings"')}${button(icon('help')+'Quick guide','help','nav-item')}<div class="profile"><span class="profile-avatar">${esc(initials(account?.name||'Demo user'))}</span><div><strong>${esc(account?.name||'Demo workspace')}</strong><small>Saved in this browser</small></div><span class="status-dot"></span></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumbs">${button(icon('menu'),'menu','icon-button mobile-menu','aria-label="Toggle navigation" aria-expanded="false"')}<span>Workspace</span>${icon('chevron')}<strong>${pageNames[page]}</strong></div><div class="topbar-tools">${uploadQueue.badge()}<button class="button small assistant-open-button" data-assistant-open aria-label="Open project assistant">${icon('spark')}<span>Assistant</span></button><label class="global-search">${icon('search')}<input id="global-search" placeholder="Find reports, datasets…" aria-label="Search all reports and datasets"><kbd>↵</kbd></label>${button(icon('help'),'help','icon-button','aria-label="Help"')}<a class="top-avatar" href="./organisation.html" aria-label="Organisation setup">${esc(initials(account?.name||'Demo user'))}</a></div></header><main id="main" tabindex="-1"><div class="project-bar"><div class="project-picker">${icon('briefcase')}<select id="project-select" aria-label="Current project">${workspace.projects.map(v=>`<option value="${esc(v.id)}" ${v.id===p.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select>${p.sample?pill('Sample project'):pill(p.type,'green')}</div><div class="project-actions"><span class="saved-status">${icon(storageError?'alert':'shield')}${storageError?'Save needs attention':'Browser workspace'}</span>${button(icon('plus')+'New project','new-project','button small')}</div></div>${views[page]()}</main><footer class="app-footer"><span>Planvisiq · Turn project data into clear results.</span><span>Frontend preview · ${p.sample?'Fictional sample data':'Files stay in this browser'}</span></footer></div>`;}
function render(){if(!project())return;$('#app').innerHTML=shell();assistant.refresh();}
function header(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function overview(){const p=project(),ts=filterTasks(tasks(p),{scope}),m=metrics(ts,p.cutoff),tr=trend(p),groups=grouped(ts,groupBy),ns=insights(p,ts),diff=m.progress!==null&&m.planned!==null?m.progress-m.planned:null;
 return header('Your project, made clear.','Upload your files. Check the results. Get your report.',button(icon('upload')+'Upload files','upload','button primary'))+quickStart()+`<div class="filterbar"><div class="tab-label">${icon('dashboard')} Project summary</div><div class="filter-controls"><label class="filter-control">${icon('layers')}<select id="scope-filter" aria-label="Filter project scope"><option value="All">All areas</option>${[...new Set(tasks(p).map(t=>t.area))].map(a=>`<option ${scope===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><label class="filter-control">${icon('calendar')}<input type="date" id="cutoff-date" aria-label="Reporting cut-off date" value="${p.cutoff}"></label></div></div><div class="kpi-grid">${kpi('Overall progress',percent(m.progress),diff===null?'Upload a schedule to begin':`${Math.abs(diff).toFixed(1)} pp ${diff<0?'behind':'ahead of'} plan`,diff!==null&&diff<0?'amber':'green','trend',miniLine(tr.filter(v=>v.actual!==null).map(v=>v.actual)))}${kpi('Activities completed',String(m.completed),`of ${m.total} scheduled activities`,'green','check',`<div class="tiny-progress"><span style="width:${m.total?m.completed/m.total*100:0}%"></span></div>`)}${kpi('Needs attention',String(m.overdue),'Past planned finish · incomplete',m.overdue?'amber':'green','clock')}${kpi('Actual costs',money(m.actualCost),m.budget!==null?`of ${money(m.budget)} activity budget`:'Add activity cost data','neutral','briefcase')}</div><div class="dashboard-charts"><section class="card progress-card"><div class="card-heading"><div><h2>Progress over time</h2><p>Recorded project progress against the plan</p></div><div class="chart-heading-actions"><button class="icon-button" data-assistant-open data-assistant-chart="trend" aria-label="Explain progress over time">${icon('spark')}</button>${button(icon('sliders'),'chart-settings','icon-button','aria-label="Customise chart"')}</div></div><div class="chart-legend"><span><i class="legend-dot actual"></i>Actual progress</span><span><i class="legend-line"></i>Planned progress</span><span class="chart-cutoff">As of ${esc(p.cutoff)}</span></div>${lineChart(tr,{bars:chartType==='bar'})}<div class="chart-foot">${icon('file')} ${latest(p,21)?esc(latest(p,21).name):'No progress history uploaded'}<span>${scope==='All'?'Whole project trend':'Trend shows whole project; scope applies to activity cards'}</span></div></section><section class="card status-card"><div class="card-heading"><div><h2>Activity status</h2><p>Every task, accounted for</p></div>${icon('layers')}</div><div class="donut-wrap"><div class="donut" style="--progress:${m.total?m.completed/m.total*100:0}%;--active:${m.total?ts.filter(t=>!completed(t)&&(t.progress??0)>0).length/m.total*100:0}%"><div><strong>${m.total}</strong><span>Total activities</span></div></div></div><div class="status-list">${[['Completed',ts.filter(completed).length,'#176b51'],['In progress',ts.filter(t=>!completed(t)&&(t.progress??0)>0).length,'#b8d2a1'],['Not started / other',ts.filter(t=>!completed(t)&&(t.progress??0)===0).length,'#e7ece5']].map(([name,n,color])=>`<div><span><i style="background:${color}"></i>${name}</span><strong>${n}</strong></div>`).join('')}</div></section></div><div class="dashboard-bottom"><section class="card"><div class="card-heading"><div><h2>Progress by ${groupBy}</h2><p>Find the work that needs a closer look</p></div><select id="group-select" class="plain-select" aria-label="Group progress by">${['discipline','area','contractor'].map(g=>`<option ${g===groupBy?'selected':''} value="${g}">By ${g}</option>`).join('')}</select></div>${groups.length?`<div class="group-table"><div class="group-table-head"><span>${groupBy}</span><span>Activities</span><span>Progress</span></div>${groups.map((g,i)=>`<button class="group-row" data-action="show-group" data-value="${esc(g.name)}"><span><i class="discipline-icon color-${i%5}">${icon(['settings','layers','trend','sliders','grid'][i%5])}</i><strong>${esc(g.name)}</strong></span><span>${g.completed}<small> / ${g.total}</small></span><span><i class="bar-track"><i style="width:${g.progress??0}%"></i></i><b>${percent(g.progress)}</b></span></button>`).join('')}</div>`:empty('No activity data yet','Upload an activity schedule to see progress by team.')}</section><section class="card insight-card"><div class="card-heading"><div class="inline-heading"><span class="insight-symbol">${icon('spark')}</span><div><h2>Your project, explained</h2><p>Checks based on your project data</p></div></div></div><div class="insight-list">${ns.slice(0,3).map((n,i)=>`<button class="insight-item" data-action="insight" data-index="${i}"><span class="insight-dot ${n.level}"></span><div><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p></div>${icon('chevron')}</button>`).join('')}</div><div class="insight-footer">${pill('Local data checks')}${button('Explore insights '+icon('arrow'),'nav','text-button','data-page="insights"')}</div></section></div><section class="report-cta"><div class="cta-art">${icon('file')}<span>${icon('check')}</span></div><div><h2>Your progress deserves a good presentation.</h2><p>Turn this view into a polished report or editable slide deck.</p></div>${button('Build your report '+icon('arrow'),'new-report','button primary')}</section>`;
}
function kpi(label,value,note,tone,ic,extra=''){return `<section class="card kpi"><div class="kpi-title">${label}${icon(ic)}</div><strong>${esc(value)}</strong><div class="kpi-bottom"><span class="${tone}">${esc(note)}</span>${extra}</div></section>`;}
function dataView(){const p=project();const catalogues=catalog.filter(c=>c.kind==='dataset'&&(!query||`${c.name} ${c.description}`.toLowerCase().includes(query.toLowerCase()))&&(category==='All categories'||c.category===category));return header('Your data, connected.','Bring your project records together in one place.',button(icon('download')+'Sample CSV','sample-csv','button')+button(icon('upload')+'Upload files','upload','button primary'))+`<div class="section-tabs">${button('Project files <span>'+p.datasets.length+'</span>','library-tab','tab '+(libraryTab==='files'?'selected':''),'data-value="files"')}${button('Dataset catalogue <span>120</span>','library-tab','tab '+(libraryTab==='catalog'?'selected':''),'data-value="catalog"')}${button('Supporting documents <span>'+p.documents.length+'</span>','library-tab','tab '+(libraryTab==='documents'?'selected':''),'data-value="documents"')}</div>${libraryTab==='catalog'?catalogToolbar('dataset'):''}${libraryTab==='files'?`<div class="dropzone" data-dropzone="data">${icon('upload')}<div><strong>Drop a spreadsheet. Get a clearer picture.</strong><p>Excel, CSV or TSV · Up to 5,000 rows per dataset · 10 MB per file</p></div>${button('Browse files','upload','button')}</div><section class="card file-card"><div class="card-heading"><h2>Uploaded datasets</h2><span class="muted">${p.datasets.length} versions</span></div>${p.datasets.length?`<div class="table-wrap"><table><thead><tr><th>File name</th><th>Dataset</th><th>Records</th><th>Data as of</th><th>Version</th><th></th></tr></thead><tbody>${[...p.datasets].reverse().map(d=>`<tr><td><div class="file-cell"><span class="file-icon">${icon('grid')}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.sheet||'Imported records')}</small></div></div></td><td>${esc(catalog.find(c=>c.id===d.catalogId)?.name||'Dataset')}</td><td>${d.rows.length.toLocaleString()}</td><td>${esc(d.asOf)}</td><td>${pill(latest(p,d.catalogId)?.id===d.id?'Current':'History',latest(p,d.catalogId)?.id===d.id?'green':'neutral')}</td><td>${button(icon('eye'),'view-dataset','icon-button',`data-id="${esc(d.id)}" aria-label="View ${esc(d.name)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your next insight starts with a file.','Upload an activity schedule, budget or any of the 120 supported dataset types.')}</section>`:libraryTab==='documents'?`<div class="notice">${icon('file')}Supporting documents are stored with this project in this browser. PDF and document data extraction will be added with the backend.</div>${button(icon('plus')+'Add supporting files','supporting-upload','button')}<div class="document-grid">${p.documents.map(d=>`<div class="card document-card">${icon('file')}<h3>${esc(d.name)}</h3><p>${(d.size/1024).toFixed(0)} KB · ${esc(d.createdAt.slice(0,10))}</p>${button(icon('download')+'Download','document-download','button small',`data-id="${d.id}"`)}</div>`).join('')||empty('Keep the evidence together.','Add photos, PDFs and other supporting files.')}</div>`:`<div class="catalog-grid">${catalogues.map(c=>`<article class="card catalog-card"><div class="catalog-top"><span class="catalog-number">D${String(c.id).padStart(3,'0')}</span>${c.priority?pill('Core dataset','green'):''}</div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="catalog-bottom"><small>${esc(c.category)}</small>${button(icon('upload'),'upload-catalog','icon-button',`data-id="${c.id}" aria-label="Upload ${esc(c.name)}"`)}</div></article>`).join('')||empty('No matching datasets','Try a different search or category.')}</div>`}`;}
function catalogToolbar(kind){return `<div class="catalog-toolbar"><label class="search-input">${icon('search')}<input id="catalog-search" placeholder="Search ${kind==='report'?'120 report templates':'120 datasets'}…" value="${esc(query)}" aria-label="Search catalogue"></label><select id="category-select" aria-label="Filter category"><option>All categories</option>${[...new Set(catalog.filter(c=>c.kind===kind).map(c=>c.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="muted">${kind==='report'?'120 templates':'120 datasets'}</span></div>`;}
function fullReportCatalogue(){const p=project();let list=catalog.filter(c=>c.kind==='report'&&(!query||`${c.name} ${c.description}`.toLowerCase().includes(query.toLowerCase()))&&(category==='All categories'||category===c.category));return header('Report studio','Your project story, ready for the room.',button(icon('plus')+'Create report','new-report','button primary'))+`<section class="studio-hero"><div><span class="eyebrow">FROM WORKSITE TO BOARDROOM</span><h2>Good work. Clearly presented.</h2><p>Choose a template, review the figures, and make it yours.<br>Export a document, a slide deck, or the data behind it.</p><div class="format-chips"><span>PDF</span><span>PowerPoint</span><span>Excel</span><span>CSV</span></div></div><div class="paper-stack"><div class="paper-back"></div><div class="paper-front"><span class="paper-tag">PROJECT REPORT</span><strong>Progress.<br>Made clear.</strong><div class="paper-bars"><i></i><i></i><i></i><i></i><i></i></div><div class="paper-line"></div><small>PLANVISIQ</small></div></div></section>${catalogToolbar('report')}<div class="catalog-grid report-grid">${list.map(c=>{const s=reportStatus(p,c.id);return `<article class="card catalog-card report-template"><div class="catalog-top"><span class="report-template-icon">${icon(c.category.includes('Executive')?'briefcase':c.category.includes('schedule')?'calendar':'file')}</span>${pill(s.ready?'Ready to review':s.implemented?'Needs data':'Template preview',s.ready?'green':s.implemented?'amber':'neutral')}</div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="template-inputs">${s.missing.length?`${s.missing.length} required dataset${s.missing.length===1?'':'s'} missing`:s.implemented?'Required datasets available':'Specialist calculations pending'}</div><div class="catalog-bottom"><small>R${c.id} · ${c.priority?'Core report':c.category.split(' ')[0]}</small>${button('Open template '+icon('arrow'),'open-report','text-button',`data-id="${c.id}"`)}</div></article>`;}).join('')||empty('No matching reports','Try a different search or category.')}</div>`;}
function quickStart(){const p=project(),review=reviewData(p),ready=!!review.dataset;return `<section class="quick-start"><div class="quick-start-heading"><div><span class="eyebrow">YOUR NEXT STEP</span><h2>${ready?'Your files are here. Let’s make them useful.':'Start with a spreadsheet. We’ll take it from there.'}</h2></div><span class="easy-label">3 simple steps</span></div><div class="journey-grid"><button data-action="upload" class="journey-step ${!ready?'current':''}"><span class="journey-number">${ready?icon('check'):'1'}</span><div><strong>Upload files</strong><p>${ready?'Add a new file or this week’s update.':'Use the Excel or CSV files you already have.'}</p></div>${icon('arrow')}</button><button data-action="review-data" class="journey-step ${ready&&review.checks.length?'current':''}"><span class="journey-number">2</span><div><strong>Check the results</strong><p>${!ready?'We’ll flag missing or conflicting information.':review.checks.length?`${review.checks.length} things to check in your schedule.`:'Basic checks passed. Take a quick look.'}</p></div>${icon('arrow')}</button><button data-action="new-report" class="journey-step ${ready&&!review.checks.length?'current':''}"><span class="journey-number">3</span><div><strong>Create your report</strong><p>Choose a purpose. We’ll prepare the layout.</p></div>${icon('arrow')}</button></div></section>`;}
function quickReportCards(){return `<div class="quick-report-grid">${quickReports.map(r=>`<button class="quick-report-card" data-action="quick-report" data-id="${r.id}"><span class="quick-report-icon">${icon(r.icon)}</span><strong>${r.title}</strong><p>${r.description}</p><span class="text-button">Prepare report ${icon('arrow')}</span></button>`).join('')}</div>`;}
function reportsView(){const p=project();return header('What would you like to share?','Choose a report. The figures, charts and layout are prepared for you.')+quickReportCards()+reportLibrary.view()+`<p class="simple-note">PDF for a document · PowerPoint for a meeting · Excel or CSV for the figures</p>${p.exports.length?`<section class="card recent-reports"><div class="card-heading"><h2>Recently downloaded</h2></div>${p.exports.slice(0,5).map(r=>`<div><span>${icon('file')} ${esc(r.name)}</span><small>${esc(r.format.toUpperCase())} · ${esc(r.date.slice(0,10))}</small></div>`).join('')}</section>`:''}<details class="advanced-catalogue"><summary>Need a different report? Browse all 120 templates ${icon('down')}</summary>${fullReportCatalogue()}</details>`;}
function chooseReport(){openModal('What do you need to share?',`<p class="quick-intro">Pick a purpose. Your project figures and company branding are already included.</p>${quickReportCards()}<div class="modal-actions">${button('Browse other reports','browse-reports','text-button')}</div>`,true);}
function reviewModal(){const review=reviewData(project());openModal('A quick check before you share',`<div class="review-summary ${review.checks.length?'has-checks':''}">${icon(review.checks.length?'alert':'check')}<div><h3>${review.checks.length?`${review.checks.length} thing${review.checks.length===1?'':'s'} to check`:'No basic schedule issues found'}</h3><p>${review.dataset?`${review.total} activities checked · ${esc(review.dataset.name)}`:'Your charts need an activity schedule.'}</p></div></div>${review.future?'<div class="notice">Your schedule is dated after the reporting date. Update the date on My project, or upload a schedule for the selected date.</div>':''}<div class="review-checks">${review.checks.map(c=>`<section><div><strong>${esc(c.title)}</strong>${c.rows.length?pill(`${c.rows.length} activities`,'amber'):''}</div><p>${esc(c.text)}</p>${c.rows.length?`<details><summary>Show activities to check</summary><div class="review-rows">${c.rows.slice(0,20).map(index=>`<button data-action="check-record" data-id="${esc(review.dataset.id)}" data-index="${index}"><span>${esc(review.dataset.rows[index][review.dataset.mapping.name]||'Unnamed activity')}<small>Source row ${index+2}</small></span>${icon('edit')}</button>`).join('')}${c.rows.length>20?`<p>${c.rows.length-20} more activities. Check the full file in Files.</p>`:''}</div></details>`:button(icon('upload')+'Upload schedule','upload-catalog','button small','data-id="11"')}</section>`).join('')}</div><p class="simple-note">These checks look for missing values and obvious conflicts. Review the figures against your source records before sharing.</p><div class="modal-actions">${button('Back to project','close-modal','button')}${button('Create a report '+icon('arrow'),'new-report','button primary')}</div>`,true);}
function tasksView(){const p=project();let ts=filterTasks(tasks(p),{scope});if(query)ts=ts.filter(t=>`${t.id} ${t.name} ${t.contractor}`.toLowerCase().includes(query.toLowerCase()));if(taskFilter==='Completed')ts=ts.filter(completed);if(taskFilter==='Needs attention')ts=ts.filter(t=>overdue(t,p.cutoff));if(taskFilter==='In progress')ts=ts.filter(t=>!completed(t)&&(t.progress??0)>0);const totalPages=Math.max(1,Math.ceil(ts.length/15));taskPage=Math.min(taskPage,totalPages);return header('Work register','A closer look at the activities behind your progress.',button(icon('download')+'Export CSV','tasks-csv','button')+button(icon('upload')+'Upload schedule','upload','button primary'))+`<div class="catalog-toolbar"><label class="search-input">${icon('search')}<input id="task-search" placeholder="Find an activity or contractor…" value="${esc(query)}" aria-label="Search activities"></label><select id="task-status" aria-label="Filter status">${['All statuses','Completed','In progress','Needs attention'].map(s=>`<option ${s===taskFilter?'selected':''}>${s}</option>`).join('')}</select>${scope!=='All'?button(esc(scope)+' '+icon('close'),'clear-scope','button small'):''}<span class="muted">${ts.length} activities</span></div><section class="card"><div class="table-wrap"><table class="task-table"><thead><tr><th>Activity</th><th>Discipline</th><th>Contractor</th><th>Progress</th><th>Planned finish</th><th>Status</th><th></th></tr></thead><tbody>${ts.slice((taskPage-1)*15,taskPage*15).map(t=>`<tr><td><small class="task-id">${esc(t.id)}</small><strong>${esc(t.name)}</strong><small>${esc(t.area)}</small></td><td>${esc(t.discipline)}</td><td>${esc(t.contractor)}</td><td><div class="progress-cell"><i class="bar-track"><i style="width:${t.progress??0}%"></i></i><b>${percent(t.progress)}</b></div></td><td>${esc(t.plannedFinish||'Not supplied')}</td><td>${pill(overdue(t,p.cutoff)?'Overdue':t.status,completed(t)?'green':overdue(t,p.cutoff)?'amber':'neutral')}</td><td>${button(icon('edit'),'edit-task','icon-button',`data-id="${esc(t.id)}" aria-label="Edit ${esc(t.name)}"`)}</td></tr>`).join('')}</tbody></table></div>${!ts.length?empty('No activities in this view','Upload a schedule or change the filters.'):''}<div class="pagination"><span>Page ${taskPage} of ${totalPages}</span><div>${button('Previous','task-prev','button small',taskPage===1?'disabled':'')}${button('Next','task-next','button small',taskPage===totalPages?'disabled':'')}</div></div></section>`;}
function insightsView(){const p=project(),ns=insights(p);return header('A clearer next step.','Understand the numbers and decide what to do next.')+`<div class="assistant-layout"><section class="card"><div class="card-heading"><div class="inline-heading"><span class="insight-symbol">${icon('spark')}</span><div><h2>Planvisiq assistant</h2><p>Local project checks</p></div></div>${pill('Frontend preview')}</div><div class="assistant-disclosure">Live AI will be connected in the backend stage. These responses use fixed calculations from your selected project.</div><div id="messages" class="messages"><div class="assistant-message"><span class="assistant-avatar">${icon('spark')}</span><div><strong>Let’s make sense of your project.</strong><p>I can summarise progress, list overdue activities and show you the source data.</p></div></div>${assistantMessages.map(m=>`<div class="chat-message ${m.role}"><div>${esc(m.text).replace(/\n/g,'<br>')}</div></div>`).join('')}</div><div class="prompt-chips">${['Summarise progress','What needs attention?','Show recorded costs','What data is missing?'].map(t=>button(esc(t),'assistant-prompt','prompt-chip',`data-value="${esc(t)}"`)).join('')}</div><form id="assistant-form" class="assistant-form"><input id="assistant-input" placeholder="Ask about progress, costs, or overdue work…" aria-label="Ask the project assistant" required><button class="button primary" aria-label="Send question">${icon('send')}</button></form></section><section><h2 class="side-title">What your data is telling you</h2>${ns.map(n=>`<article class="card insight-detail"><span class="insight-dot ${n.level}"></span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.ids.length?`<small>Source activities: ${esc(n.ids.slice(0,8).join(', '))}${n.ids.length>8?'…':''}</small>`:''}</article>`).join('')}${button(icon('tasks')+'Open source activities','nav','button','data-page="tasks"')}</section></div>`;}
function settingsView(){const p=project();return header('Make it your workspace.','Set your report identity and keep a copy of your work.')+companyTemplates.settings()+`<div class="settings-grid"><form id="settings-form" class="card settings-card"><h2>Project and report identity</h2><label>Project name<input name="name" value="${esc(p.name)}" required maxlength="100"></label><label>Client name<input name="client" value="${esc(p.client)}" maxlength="100"></label><label>Company name<input name="company" value="${esc(p.company)}" maxlength="100"></label><label>Company logo</label><div class="brand-upload">${p.logo?`<img src="${esc(p.logo)}" alt="Company logo">`:icon('briefcase')}${button('Upload logo','upload-logo','button small')}${p.logo?button('Remove','remove-logo','text-button'):''}</div><label>Report accent colour<input name="color" type="color" value="${p.color||'#176b51'}"></label><label>Reporting cut-off<input name="cutoff" type="date" value="${p.cutoff}" required></label><button class="button primary">Save changes</button></form><div><section class="card settings-card"><h2>Your data stays with you</h2><p>This is the HTML, CSS and JavaScript frontend. Projects and supporting files are stored in this browser using IndexedDB. They are not uploaded to a server.</p><p>Export a backup before clearing browser data or switching devices. Live AI, shared workspaces and cloud storage are part of the backend stage.</p>${button(icon('download')+'Export workspace backup','backup','button primary')}${button(icon('upload')+'Restore a backup','restore','button')}</section><section class="card settings-card"><h2>The full product scope</h2><p>All 120 dataset types and 120 report templates are included. Templates marked “Template preview” show the required inputs and supporting records; their specialist analysis is still to be implemented.</p><a href="./docs/full-catalogue.md" download class="button">${icon('download')}Download complete catalogue</a></section></div></div>`;}
const views={overview,data:dataView,tasks:tasksView,reports:reportsView,slides:()=>slideStudio.view(),insights:insightsView,settings:settingsView};
function openModal(title,body,wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<dialog class="modal ${wide?'wide':''}" id="dialog"><div class="modal-header"><h2>${title}</h2>${button(icon('close'),'close-modal','icon-button','aria-label="Close dialog"')}</div><div class="modal-body">${body}</div></dialog>`;const dialog=$('#dialog');dialog.showModal();dialog.addEventListener('click',e=>{if(e.target===dialog)closeModal();});dialog.addEventListener('cancel',()=>{uploadQueue.closeReview();modalFocus?.focus();});assistant.refresh();}
function closeModal(){const d=$('#dialog');if(d){d.close();d.remove();}modalFocus?.focus();}
function newProjectModal(){openModal('A fresh start for your next project',`<form id="new-project-form" class="form-stack"><p class="muted">Add your project details, then bring in your first spreadsheet.</p><label>Project name<input name="name" placeholder="e.g. October refinery shutdown" required maxlength="100" autofocus></label><div class="form-row"><label>Client<input name="client" placeholder="Client organisation" maxlength="100"></label><label>Project type<select name="type"><option>Shutdown & turnaround</option><option>Construction</option><option>Civil engineering</option><option>Maintenance</option><option>Water infrastructure</option><option>Other project</option></select></label></div><label>Your company<input name="company" value="${esc(project().company)}" maxlength="100"></label><label>Reporting cut-off<input type="date" name="cutoff" value="${today()}" required></label><div class="modal-actions">${button('Cancel','close-modal','button')}<button class="button primary">Create project ${icon('arrow')}</button></div></form>`);}
function pickFile(accept,callback,multiple=false){const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;input.addEventListener('change',()=>{if(input.files?.length)callback(multiple?[...input.files]:input.files[0]);});input.click();}
async function startImport(file,catalogId=null,prepared=null,asOf=project().cutoff){try{pendingFile=file;pendingDate=asOf;pendingSheets=prepared||await readFile(file);pendingSheet=0;if(!pendingSheets.length)throw new Error('No populated worksheets were found.');for(const sheet of prepared?[]:pendingSheets){const suggestion=importSuggestion(sheet,file.name,project().importPreferences||[]);sheet.mapping=suggestion.mapping;sheet.catalogId=catalogId||suggestion.catalogId;sheet.remembered=!catalogId&&suggestion.remembered;}pendingCatalog=pendingSheets[0].catalogId;renderImport();}catch(e){toast(e.message,true);}}
function rememberImportDraft(){const form=$('#import-form');if(!form)return;const f=new FormData(form),sheet=pendingSheets[pendingSheet];sheet.mapping={};for(const key of Object.keys(fields))if(f.get('map-'+key))sheet.mapping[key]=f.get('map-'+key);sheet.catalogId=Number(f.get('catalog'))||null;pendingDate=f.get('asOf');}
function renderImport(){const sheet=pendingSheets[pendingSheet],headers=Object.keys(sheet.rows[0]||{}),kind=catalog.find(c=>c.id===sheet.catalogId),needMatches=!kind||(sheet.catalogId===11&&(!sheet.mapping.id||!sheet.mapping.name));pendingCatalog=sheet.catalogId;openModal('We’ve opened your file',`<div class="import-file">${icon('grid')}<div><strong>${esc(pendingFile.name)}</strong><p>${sheet.rows.length.toLocaleString()} rows · ${kind?esc(kind.name):'Choose what this file contains below'}</p></div>${pill(sheet.remembered?'Saved column matches':kind?'Suggested file type':'Choose file type',kind?'green':'amber')}</div><form id="import-form"><div class="import-simple-summary"><strong>${sheet.remembered?'Your previous column choices are filled in.':'We’ve matched the columns we recognise.'}</strong><p>Check the date, then add the file. You can change any suggested match below.</p><div class="matched-columns">${Object.entries(sheet.mapping).slice(0,4).map(([k,h])=>`<span>${esc(h)} ${icon('arrow')} ${esc(fields[k])}</span>`).join('')||'<span>No familiar columns found. Choose the matches below.</span>'}</div></div><div class="form-row">${pendingSheets.length>1?`<label>Worksheet<select id="import-sheet">${pendingSheets.map((v,i)=>`<option value="${i}" ${i===pendingSheet?'selected':''}>${esc(v.name)} (${v.rows.length} rows)</option>`).join('')}</select></label>`:''}<label>These figures are up to<input name="asOf" type="date" value="${esc(pendingDate)}" required><small>This becomes the project’s reporting date.</small></label></div><details class="import-options" ${needMatches?'open':''}><summary>${needMatches?'Choose file type and column matches':'Change file type or column matches'} ${icon('down')}</summary><label>What does this file contain?<select id="import-kind" name="catalog" required><option value="">Choose a file type</option>${catalog.filter(c=>c.kind==='dataset').map(c=>`<option value="${c.id}" ${pendingCatalog===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="simple-note">For an activity schedule, match the task ID and name. Leave any columns you don’t have as “Not in this file”.</p><div class="mapping-grid">${Object.entries(fields).map(([key,label])=>`<label>${esc(label)}<select name="map-${key}"><option value="">Not in this file</option>${headers.map(h=>`<option value="${esc(h)}" ${sheet.mapping[key]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div></details><details class="preview-details"><summary>See the first ${Math.min(5,sheet.rows.length)} rows</summary><div class="table-wrap">${rawTable(sheet.rows.slice(0,5))}</div></details><div id="import-errors" class="form-errors" role="alert" tabindex="-1"></div><div class="modal-actions"><span class="muted">Your original values are kept. Confirmed matches are remembered.</span><button type="submit" class="button primary">Add file & check results ${icon('arrow')}</button></div></form>`,true);}
function rawTable(rows){if(!rows.length)return empty('No records','There are no rows to show.');const headers=[...new Set(rows.flatMap(Object.keys))];return `<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${esc(r[h]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function viewDataset(id){const ds=project().datasets.find(d=>d.id===id);if(!ds)return;openModal(esc(ds.name),`<div class="dataset-meta">${pill(catalog.find(c=>c.id===ds.catalogId)?.name||'Dataset','green')}<span>${ds.rows.length} records · as of ${esc(ds.asOf)}</span></div><div class="table-wrap dataset-preview">${rawTable(ds.rows.slice(0,100))}</div><p class="muted">Showing ${Math.min(ds.rows.length,100)} of ${ds.rows.length} records. Exports include every row.</p><div class="modal-actions">${button(icon('edit')+'Edit a record','edit-record','button',`data-id="${id}"`)}${button(icon('download')+'Excel','dataset-xlsx','button',`data-id="${id}"`)}${button(icon('download')+'CSV','dataset-csv','button primary',`data-id="${id}"`)}</div>`,true);}
function defaultOptions(id){const pref=project().reportPreferences||{};return {scope:'All',groupBy:pref.groupBy||groupBy,from:'',to:'',audience:pref.audience||'Client stakeholders',detail:pref.detail||'Executive summary',commentary:'',includeCharts:true,includeTables:true,includeSources:true,title:catalog.find(c=>c.id===id)?.name||'Project report',...companyTemplates.reportDefaults(id)};}
function reportModal(id=121,quick=false){activeReport={id,options:defaultOptions(id),format:project().reportPreferences?.format||'pdf',source:companyTemplates.branded(project())};if(quick&&id===121){activeReport.options.quickSummary=true;activeReport.options.title='Project progress update';}renderReportModal();}
function renderReportModal(){const p=activeReport.source||companyTemplates.branded(project()),{id,options:o}=activeReport,r=createReport(p,id,o),allScopes=[...new Set(tasks(p).flatMap(t=>[t.area,t.discipline,t.contractor]))];openModal('Your report is ready to personalise',`<div class="report-builder"><form id="report-form" class="report-controls"><div class="report-auto-note">${icon('check')} Figures, charts and branding filled in for you.</div>${companyTemplates.reportPicker()}<button type="button" class="text-button" data-assistant-open>${icon('spark')}Help with this report</button><label>Report title<input name="title" value="${esc(o.title)}" maxlength="150" required></label><details class="report-advanced"><summary>More options <span>Layout, audience and filters</span>${icon('down')}</summary><label>Report template<select name="template" id="report-template">${catalog.filter(c=>c.kind==='report').map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="form-row"><label>Audience<select name="audience">${['Client stakeholders','Executive management','Project team'].map(v=>`<option ${o.audience===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Detail<select name="detail">${['Executive summary','Detailed report'].map(v=>`<option ${o.detail===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Scope<select name="scope"><option value="All">Whole project</option>${allScopes.map(v=>`<option ${o.scope===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="form-row"><label>From<input name="from" type="date" value="${o.from}"></label><label>To<input name="to" type="date" value="${o.to}"></label></div><small class="field-note">Period filters activity planned finish dates. Cut-off: ${p.cutoff}.</small><label>Commentary<textarea name="commentary" rows="5" placeholder="An automatic factual summary is included. Add your own commentary here to replace it.">${esc(o.commentary)}</textarea></label><div class="check-row">${[['includeCharts','Charts'],['includeTables','Records'],['includeSources','Sources']].map(([k,n])=>`<label><input type="checkbox" name="${k}" ${o[k]?'checked':''}>${n}</label>`).join('')}</div></details><label>What would you like to download?<select name="format">${[['pdf','PDF document'],['pptx','Editable PowerPoint'],['xlsx','Excel workbook'],['csv','CSV records'],['zip','All formats · ZIP package']].map(([v,n])=>`<option value="${v}" ${activeReport.format===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="report-buttons"><button type="button" class="button" data-action="save-report">${icon('file')}Save draft</button><button type="button" class="button" data-action="preview-report">${icon('eye')}Update preview</button><button type="submit" class="button primary">${icon('download')}Download report</button></div></form><div class="report-preview"><div class="preview-label">DOCUMENT PREVIEW${r.review?pill('Review copy','amber'):pill('Ready to review','green')}</div><article class="report-paper">${p.logo?`<img class="preview-logo" src="${esc(p.logo)}" alt="Company logo">`:""}<div class="paper-brand" style="color:${esc(p.color)}">${esc(p.company||'PLANVISIQ')}</div><span class="eyebrow">${esc(o.audience)}</span><h2>${esc(r.title)}</h2><p class="report-project">${esc(p.name)}<br>${esc(p.client)} · ${esc(p.cutoff)}</p>${p.sample?'<small class="sample-watermark">FICTIONAL SAMPLE PROJECT</small>':''}<div class="report-rule"></div><h3>Executive summary</h3><p>${esc(r.narrative)}</p><div class="report-preview-kpis"><div><strong>${r.metrics.completed}/${r.metrics.total}</strong><span>Activities complete</span></div><div><strong>${percent(r.metrics.progress)}</strong><span>Recorded progress</span></div></div>${o.includeCharts?`<h3>Progress by ${esc(o.groupBy)}</h3><div class="report-bars">${r.groups.map(g=>`<div><span>${esc(g.name)}</span><i class="bar-track"><i style="width:${g.progress??0}%"></i></i><b>${percent(g.progress)}</b></div>`).join('')}</div>`:''}${r.review?`<div class="report-warning"><strong>Review before issue</strong>${r.missing.length?`<p>Missing: ${esc(r.missing.join(', '))}.</p>`:''}${r.specialistPending?'<p>This template currently presents supporting records. Specialist calculations are pending.</p>':''}</div>`:''}${o.includeTables?`<h3>Supporting records</h3><p>${r.rows.length} records included${o.detail==='Executive summary'?' · slides show up to 12 records':''}.</p>`:''}${r.id===240?`<h3>Close-out evidence</h3>${r.sections.filter(s=>/punch|acceptance|lessons/i.test(s.title)).map(s=>`<p>${esc(s.title)} · ${s.rows.length} records</p>`).join('')}`:''}${o.includeSources?`<div class="preview-sources"><strong>SOURCES & CALCULATIONS</strong><p>${r.sources.map(s=>esc(s.name)).join('<br>')||'No source datasets available.'}</p><p>${r.metrics.weighted?'Supplied progress weights.':'Unweighted average of available activity progress values.'} Recorded completion is separate from client acceptance.</p></div>`:''}</article></div></div>`,true);}
function gatherReport(){const form=$('#report-form'),f=new FormData(form);if(f.get('from')&&f.get('to')&&f.get('from')>f.get('to'))throw new Error('The start date must be on or before the end date.');activeReport.options={...activeReport.options,title:f.get('title'),audience:f.get('audience'),detail:f.get('detail'),scope:f.get('scope'),from:f.get('from'),to:f.get('to'),commentary:f.get('commentary'),includeCharts:f.has('includeCharts'),includeTables:f.has('includeTables'),includeSources:f.has('includeSources')};activeReport.format=f.get('format');}
function editTaskModal(id){const t=tasks(project()).find(t=>t.id===id);if(!t)return;openModal('Update activity',`<form id="edit-task-form" data-id="${esc(id)}" class="form-stack"><div class="dataset-meta">${pill(t.id,'green')}<strong>${esc(t.name)}</strong></div><div class="form-row"><label>Progress (%)<input name="progress" type="number" min="0" max="100" step="0.1" value="${t.progress??''}" required></label><label>Status<select name="status">${[...new Set([t.status,'Not started','In progress','Completed','Blocked','Deferred','Cancelled'])].map(s=>`<option ${s===t.status?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div><label>Actual finish date<input name="actualFinish" type="date" value="${t.actualFinish}"></label><p class="muted">Saving creates a new schedule version. Previous imported records remain available.</p><div class="modal-actions"><button class="button primary">Save activity</button></div></form>`);}
function answer(question){const p=project(),m=metrics(tasks(p),p.cutoff);let reply;const q=question.toLowerCase();if(/cost|budget|spen/.test(q))reply=`Recorded activity cost: ${money(m.actualCost)}.\nActivity budget: ${money(m.budget)}.\nThese figures do not include unrecorded commitments or forecast remaining costs.\nSource: ${latest(p,11)?.name||'No activity schedule'}.`;else if(/attention|late|overdue|delay/.test(q)){const list=tasks(p).filter(t=>overdue(t,p.cutoff));reply=list.length?`${list.length} activities are past their planned finish at ${p.cutoff}:\n\n${list.map(t=>`${t.id} · ${t.name} · planned finish ${t.plannedFinish}`).join('\n')}\n\nReview remaining work with the named contractors. This does not establish a critical-path delay.`:'No overdue activities were found in the available schedule. This does not confirm that all project risks are resolved.';}else if(/missing|quality|data/.test(q)){const s=reportStatus(p,240);reply=`For the final close-out template, ${s.missing.length?s.missing.map(n=>catalog.find(c=>c.id===n).name).join(', '):'all required dataset types are present'}.\n${m.missingProgress} activities have no progress percentage.\nPresence of a dataset does not confirm it is complete, correct or approved.`;}else if(/progress|summar|status|complet/.test(q))reply=narrative(p,defaultOptions(121))+`\n\nSource: ${latest(p,11)?.name||'No activity schedule'}.`;else reply='In this frontend I can summarise progress, list overdue work, show recorded costs and identify missing close-out datasets. Live AI and open-ended project questions will be connected in the backend stage.';assistantMessages.push({role:'user',text:question},{role:'assistant',text:reply});render();$('#messages')?.scrollTo(0,$('#messages').scrollHeight);}
async function backup(){await slideStudio.flush();const zip=new JSZip();zip.file('workspace.json',JSON.stringify({version:1,workspace},null,2));let missing=0;for(const p of workspace.projects)for(const f of p.documents){const blob=await getFile(f.id);if(blob)zip.file('files/'+f.id,blob);else missing++;}download(await zip.generateAsync({type:'blob'}),'Planvisiq_Workspace_Backup.zip');toast(missing?`Backup created; ${missing} supporting files were unavailable.`:'Workspace backup downloaded.');}
async function restore(file){try{if(file.size>100*1024*1024)throw new Error('Use a backup smaller than 100 MB.');const zip=await JSZip.loadAsync(file),entry=zip.file('workspace.json');if(!entry)throw new Error('This is not a Planvisiq workspace backup.');const data=JSON.parse(await entry.async('string'));if(data.version!==1||!Array.isArray(data.workspace?.projects)||data.workspace.projects.length>100)throw new Error('The workspace backup format is not supported.');const restored=[];for(const p of data.workspace.projects){if(typeof p.name!=='string'||!Array.isArray(p.datasets)||!Array.isArray(p.documents)||!/^\d{4}-\d{2}-\d{2}$/.test(p.cutoff))throw new Error('The backup has invalid project records.');for(const d of p.datasets)if(!Array.isArray(d.rows)||d.rows.length>5000||!d.mapping||!catalog.some(c=>c.id===d.catalogId&&c.kind==='dataset'))throw new Error('The backup has an invalid dataset.');const copy={...p,id:uid(),name:p.name+' (restored)',exports:p.exports||[]};copy.color=/^#[0-9a-f]{6}$/i.test(copy.color)?copy.color:'#176b51';if(!/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(copy.logo||''))delete copy.logo;copy.documents=[];for(const f of p.documents){const dataFile=zip.file('files/'+f.id);if(dataFile){const newId=uid();await saveFile(newId,await dataFile.async('blob'));copy.documents.push({...f,id:newId});}}slideStudio.normalizeProject(copy);normalizeSavedReports(copy);restored.push(copy);}workspace.projects.push(...restored);const assets={companyBrand:data.workspace.companyBrand,companyTemplates:data.workspace.companyTemplates,defaultReportStyle:data.workspace.defaultReportStyle};normalizeCompanyAssets(assets);if(!workspace.companyBrand&&assets.companyBrand)workspace.companyBrand=assets.companyBrand;workspace.companyTemplates=workspace.companyTemplates||[];for(const t of assets.companyTemplates){if(workspace.companyTemplates.length>=30)break;const original=t.id;t.id=uid();t.name=t.name+' (restored)';workspace.companyTemplates.push(t);if(!workspace.defaultReportStyle&&assets.defaultReportStyle===original)workspace.defaultReportStyle=t.id;}await persist();currentId=restored[0]?.id||currentId;render();toast(`${restored.length} projects restored as new copies.`);}catch(e){toast(e.message,true);}}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action;e.preventDefault();try{switch(a){
case 'nav':navigate(target.dataset.page);break;
case 'menu':{const open=$('.sidebar').classList.toggle('mobile-open');target.setAttribute('aria-expanded',String(open));break;}
case 'close-modal':returnToReview=false;uploadQueue.closeReview();closeModal();break;
case 'new-project':if(uploadQueue.hasPending())throw new Error('Finish or skip the queued files before creating another project.');newProjectModal();break;
case 'upload-logo':pickFile('.png,.jpg,.jpeg',async file=>{if(file.size>1024*1024){toast('Choose a logo smaller than 1 MB.',true);return;}if(!['image/png','image/jpeg'].includes(file.type)){toast('Choose a PNG or JPEG logo.',true);return;}const reader=new FileReader();reader.onload=async()=>{project().logo=reader.result;await persist();render();};reader.readAsDataURL(file);});break;
case 'remove-logo':delete project().logo;await persist();render();break;
case 'new-report':chooseReport();break;
case 'quick-report':reportModal(Number(target.dataset.id),true);break;
case 'browse-reports':closeModal();navigate('reports');$('.advanced-catalogue').open=true;break;
case 'review-data':reviewModal();break;
case 'check-record':returnToReview=true;editRecordModal(target.dataset.id,Number(target.dataset.index));break;
case 'open-report':reportModal(Number(target.dataset.id));break;
case 'upload':pickFile('.csv,.tsv,.xlsx',files=>uploadQueue.enqueue(files).catch(e=>toast(e.message,true)),true);break;
case 'upload-catalog':pickFile('.csv,.tsv,.xlsx',files=>uploadQueue.enqueue(files,Number(target.dataset.id)).catch(e=>toast(e.message,true)),true);break;
case 'library-tab':libraryTab=target.dataset.value;query='';category='All categories';render();break;
case 'sample-csv':download(toCSV(sampleProject().datasets[0].rows),'Planvisiq_Sample_Activity_Schedule.csv','text/csv;charset=utf-8');break;
case 'view-dataset':viewDataset(target.dataset.id);break;
case 'edit-record':editRecordModal(target.dataset.id,0);break;
case 'dataset-csv':{const d=project().datasets.find(d=>d.id===target.dataset.id);download(toCSV(d.rows),safeName(d.name)+'.csv','text/csv;charset=utf-8');break;}
case 'dataset-xlsx':{const d=project().datasets.find(d=>d.id===target.dataset.id);download(await datasetXlsx(d),safeName(d.name)+'.xlsx');break;}
case 'tasks-csv':{const r=createReport(project(),121,defaultOptions(121));download(toCSV(r.rows),'Planvisiq_Activities.csv','text/csv;charset=utf-8');break;}
case 'show-group':scope=target.dataset.value;navigate('tasks');break;
case 'clear-scope':scope='All';render();break;
case 'task-prev':taskPage=Math.max(1,taskPage-1);render();break;
case 'task-next':taskPage++;render();break;
case 'edit-task':editTaskModal(target.dataset.id);break;
case 'preview-report':gatherReport();renderReportModal();break;
case 'resume-report':renderReportModal();break;
case 'save-report':gatherReport();activeReport.source=activeReport.source||companyTemplates.branded(project());await reportLibrary.save(activeReport);render();break;
case 'insight':navigate('insights');break;
case 'assistant-prompt':answer(target.dataset.value);break;
case 'backup':target.disabled=true;target.textContent='Preparing backup…';await backup();render();break;
case 'restore':pickFile('.zip',restore);break;
case 'supporting-upload':pickFile('.pdf,.doc,.docx,.txt,.md,.png,.jpg,.jpeg,.webp',async files=>{for(const f of files){if(f.size>10*1024*1024){toast(`${f.name}: choose a file smaller than 10 MB.`,true);continue;}const id=uid();await saveFile(id,f);project().documents.push({id,name:f.name,size:f.size,createdAt:new Date().toISOString()});}await persist();render();toast('Supporting files added to this browser.');},true);break;
case 'document-download':{const f=project().documents.find(f=>f.id===target.dataset.id);const blob=await getFile(f.id);if(!blob)throw new Error('This file is no longer available in this browser.');download(blob,f.name);break;}
case 'chart-settings':openModal('Make this chart yours',`<form id="chart-form" class="form-stack"><label>Progress chart style<select name="style"><option value="line" ${chartType==='line'?'selected':''}>Line chart with filled area</option><option value="bar" ${chartType==='bar'?'selected':''}>Column chart</option></select></label><label>Group activity progress by<select name="group">${['discipline','area','contractor'].map(v=>`<option ${groupBy===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="muted">Charts use the same recorded figures as your report exports.</p><button class="button primary">Apply changes</button></form>`);break;
case 'help':openModal('From files to a finished report',`<div class="quick-guide"><p><a class="button primary" href="./learn.html">Watch the 3D walkthrough ↗</a></p>${[['1','Upload your files','Choose your Excel or CSV file. Recognised columns are matched for you, and confirmed matches are remembered.'],['2','Check the results','Review any missing or conflicting values. Your charts update from the imported records.'],['3','Download your report','Choose a progress update, weekly report or close-out pack. Select PDF, PowerPoint, Excel or CSV.']].map(([n,t,d])=>`<div><b>${n}</b><section><h3>${t}</h3><p>${d}</p></section></div>`).join('')}<div class="notice">${icon('shield')}This frontend saves to your browser. Use Settings → Export workspace backup to keep a portable copy.</div></div>`);break;
}}catch(err){toast(err.message||'Something went wrong. Please try again.',true);target.disabled=false;}});
document.addEventListener('change',e=>{const el=e.target;switch(el.id){case 'project-select':if(uploadQueue.hasPending()){el.value=project().id;toast('Finish or skip the queued files before changing projects.',true);break;}slideStudio.flush();currentId=el.value;scope='All';query='';assistantMessages=[];render();break;case 'scope-filter':scope=el.value;render();break;case 'cutoff-date':if(el.value){project().cutoff=el.value;persist();render();}break;case 'group-select':groupBy=el.value;render();break;case 'category-select':category=el.value;render();break;case 'task-status':taskFilter=el.value;taskPage=1;render();break;case 'edit-record-index':editRecordModal(el.dataset.id,Number(el.value)-1);break;case 'import-sheet':{const next=Number(el.value);rememberImportDraft();pendingSheet=next;renderImport();break;}case 'import-kind':rememberImportDraft();pendingCatalog=Number(el.value);break;case 'report-template':gatherReport();activeReport.id=Number(el.value);activeReport.options.quickSummary=false;activeReport.options.title=catalog.find(c=>c.id===activeReport.id).name;renderReportModal();break;}});
let inputTimer;document.addEventListener('input',e=>{const el=e.target;if(['catalog-search','task-search'].includes(el.id)){const id=el.id,pos=el.selectionStart;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{query=el.value;taskPage=1;render();const next=$('#'+id);next?.focus();next?.setSelectionRange(pos,pos);},180);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='global-search'){const q=e.target.value.trim();if(!q)return;const results=catalog.filter(c=>`${c.name} ${c.description}`.toLowerCase().includes(q.toLowerCase()));openModal(`Search results for “${esc(q)}”`,`<p class="muted">${results.length} matches in the complete catalogue.</p><div class="search-results">${results.slice(0,40).map(c=>`<button data-action="${c.kind==='report'?'open-report':'upload-catalog'}" data-id="${c.id}">${icon(c.kind==='report'?'file':'grid')}<div><strong>${esc(c.name)}</strong><small>${esc(c.kind)} · ${esc(c.category)}</small></div>${icon('chevron')}</button>`).join('')||empty('No matching items','Try “progress”, “cost”, “shutdown”, or “handover”.')}</div>`);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['new-project-form','import-form','report-form','edit-task-form','assistant-form','settings-form','chart-form','edit-record-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form),submit=form.querySelector('[type="submit"],button:not([type="button"])');try{
if(form.id==='new-project-form'){const p={id:uid(),name:f.get('name').trim(),client:f.get('client').trim(),company:f.get('company').trim(),type:f.get('type'),color:'#176b51',cutoff:f.get('cutoff'),datasets:[],documents:[],exports:[]};if(!p.name)throw new Error('Please enter a project name.');workspace.projects.push(p);currentId=p.id;scope='All';page='overview';await persist();closeModal();render();toast('Project created. Add your first file to get started.');}
if(form.id==='import-form'){if(importBusy)return;const sheet=pendingSheets[pendingSheet],mapping={};for(const key of Object.keys(fields))if(f.get('map-'+key))mapping[key]=f.get('map-'+key);const catalogId=Number(f.get('catalog'));if(!catalog.some(c=>c.kind==='dataset'&&c.id===catalogId))throw new Error('Choose what this file contains.');const errors=validateRows(sheet.rows,mapping,catalogId);if(errors.length){$('#import-errors').innerHTML=errors.map(x=>`<p>${icon('alert')}${esc(x)}</p>`).join('');$('.import-options').open=true;$('#import-errors').focus();return;}if(!f.get('asOf'))throw new Error('Choose the reporting date for this file.');importBusy=true;if(submit){submit.disabled=true;submit.textContent='Adding your file…';}try{sheet.mapping=mapping;sheet.catalogId=catalogId;const queued=uploadQueue.active(),job=queued||{file:pendingFile,sheet};job.sheet=sheet;const ds=await commitQueuedDataset(job,f.get('asOf'));closeModal();page='overview';scope='All';render();if(!uploadQueue.imported(ds))reviewModal();toast('File added. Your charts have been updated.');}finally{importBusy=false;if(submit){submit.disabled=false;submit.textContent='Add file & check results';}}}
if(form.id==='report-form'){gatherReport();const r=createReport(activeReport.source||companyTemplates.branded(project()),activeReport.id,activeReport.options);if(submit){submit.disabled=true;submit.innerHTML='Preparing your files…';}await exportReport(r,activeReport.format);activeReport.source=activeReport.source||companyTemplates.branded(project());await reportLibrary.save(activeReport,false);project().reportPreferences={format:activeReport.format,audience:activeReport.options.audience,detail:activeReport.options.detail,groupBy:activeReport.options.groupBy};project().exports.unshift({id:uid(),name:r.title,format:activeReport.format,date:new Date().toISOString()});project().exports=project().exports.slice(0,100);await persist();toast(`${activeReport.format.toUpperCase()} downloaded.`);renderReportModal();}
if(form.id==='edit-task-form'){const p=project(),source=latest(p,11),id=form.dataset.id,ds=structuredClone(source);ds.id=uid();ds.importedAt=new Date().toISOString();ds.name=source.name.replace(/ · edited$/,'')+' · edited';ds.asOf=p.cutoff;const t=tasks(p).find(t=>t.id===id);const row=ds.rows[t.row-2];for(const [key,value]of Object.entries({progress:Number(f.get('progress')),status:f.get('status'),actualFinish:f.get('actualFinish')})){const header=ds.mapping[key]||fields[key];ds.mapping[key]=header;row[header]=value;}if(Number(f.get('progress'))<100&&f.get('status')==='Completed')throw new Error('Set progress to 100% when marking an activity Completed.');if(Number(f.get('progress'))===100&&['Not started','Blocked','In progress'].includes(f.get('status')))throw new Error('Choose a completed status when progress is 100%.');p.datasets.push(ds);await persist();closeModal();render();toast('Activity saved as a new schedule version.');}
if(form.id==='assistant-form'){const input=$('#assistant-input'),q=input.value.trim();if(q)answer(q);}
if(form.id==='settings-form'){const p=project();for(const key of ['name','client','company','color','cutoff'])p[key]=f.get(key);await persist();render();toast('Project identity updated.');}
if(form.id==='edit-record-form'){const source=project().datasets.find(d=>d.id===form.dataset.id),ds=structuredClone(source),rowIndex=Number(form.dataset.row),keys=Object.keys(ds.rows[rowIndex]);keys.forEach((key,i)=>{const value=f.get('cell-'+i);ds.rows[rowIndex][key]=typeof source.rows[rowIndex][key]==='number'&&value!==''?Number(value):value;});const errors=validateRows(ds.rows,ds.mapping,ds.catalogId);if(errors.length)throw new Error(errors.join(' '));ds.id=uid();ds.asOf=project().cutoff;ds.importedAt=new Date().toISOString();ds.name=source.name.replace(/ · edited$/,'')+' · edited';project().datasets.push(ds);await persist();closeModal();render();toast('Record saved in a new dataset version.');if(returnToReview){returnToReview=false;reviewModal();}}
if(form.id==='chart-form'){chartType=f.get('style');groupBy=f.get('group');closeModal();render();}
}catch(err){toast(err.message||'This action could not be completed.',true);if(form.id==='report-form')renderReportModal();}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-dropzone]');if(zone){e.preventDefault();zone.classList.add('dragging');}});document.addEventListener('dragleave',e=>e.target.closest?.('[data-dropzone]')?.classList.remove('dragging'));document.addEventListener('drop',e=>{const zone=e.target.closest('[data-dropzone]');if(zone){e.preventDefault();zone.classList.remove('dragging');if(e.dataTransfer.files[0])uploadQueue.enqueue([...e.dataTransfer.files]).catch(err=>toast(err.message,true));}});
function initialProject(){return organisation.demo?sampleProject():{id:uid(),name:'Your first project',client:'',company:organisation.name,type:'Construction',color:'#176b51',cutoff:today(),datasets:[],documents:[],exports:[]};}
async function boot(){try{const saved=await loadWorkspace(workspaceKey);if(saved?.projects?.length)workspace=saved;else{workspace={projects:[initialProject()]};await persist();}}catch{workspace={projects:[initialProject()]};storageError=true;toast('Browser storage is unavailable. Export a backup to keep your changes.',true);}normalizeCompanyAssets(workspace);workspace.projects.forEach(p=>{slideStudio.normalizeProject(p);normalizeSavedReports(p);});currentId=workspace.projects[0].id;if(Object.hasOwn(pageNames,window.location.hash.slice(1)))page=window.location.hash.slice(1);render();}
boot();

function editRecordModal(id,index){const ds=project().datasets.find(d=>d.id===id);if(!ds)return;index=Math.max(0,Math.min(ds.rows.length-1,index));const row=ds.rows[index];openModal('Edit dataset record',`<form id="edit-record-form" data-id="${id}" data-row="${index}" class="form-stack"><label>Record number<input id="edit-record-index" data-id="${id}" type="number" min="1" max="${ds.rows.length}" value="${index+1}"></label><div class="mapping-grid">${Object.entries(row).map(([key,value],i)=>`<label>${esc(key)}<input name="cell-${i}" type="${typeof value==='number'?'number':'text'}" ${typeof value==='number'?'step="any"':''} value="${esc(value??'')}"></label>`).join('')}</div><p class="muted">Saving creates a new version dated ${project().cutoff}. Previous versions remain available.</p><button class="button primary">Save record</button></form>`,true);}

async function commitQueuedDataset(job,asOf){const p=project(),sheet=job.sheet,errors=validateRows(sheet.rows,sheet.mapping,sheet.catalogId);if(errors.length)throw new Error(errors.join(' '));if(!/^\d{4}-\d{2}-\d{2}$/.test(asOf))throw new Error('Choose a valid reporting date.');let ds=p.datasets.find(d=>d.id===job.datasetId);if(!ds){ds={id:uid(),catalogId:sheet.catalogId,name:job.file.name,sheet:sheet.name,rows:sheet.rows,mapping:{...sheet.mapping},asOf,importedAt:new Date().toISOString()};p.datasets.push(ds);job.datasetId=ds.id;}p.cutoff=asOf;const signature=headerSignature(Object.keys(sheet.rows[0]));p.importPreferences=[{signature,catalogId:sheet.catalogId,mapping:{...sheet.mapping}},...(p.importPreferences||[]).filter(v=>v.signature!==signature)].slice(0,30);if(!await persist())throw new Error('The file is in memory but could not be saved. Free browser storage and retry, or export a backup.');return ds;}
